select u.*, d.name as dept_name, r.name as role_name from user u left join dept d on u.dept_id = d.id left join role r on u.role_id = r.id
and u.name like concat('%', #{userRequest.name}, '%')
and u.status = #{userRequest.status}
and u.phone like concat('%', #{userRequest.phone}, '%')
and u.dept_id = #{userRequest.deptId}
order by u.create_time desc

select user.*
from user,role
where role_id = (select role.id where label = #{roleLabel});
